list($k, $w) = explode(' ', $line);
$k = (int)$k;
$w = (int)$w;

// If w is greater than or equal to k, there are infinitely many strings
if ($w >= $k) {
    echo "-1\n";
    exit;
}

// Calculate the number of valid strings
// The answer is k * (k-1) * (k-2) * ... * (k-w+1) * (k-w)^w
// But we need to compute this modulo 1000000007

$mod = 1000000007;

// Compute the product (k) * (k-1) * ... * (k-w+1)
$result = 1;
for ($i = 0; $i < $w; $i++) {
    $result = ($result * ($k - $i)) % $mod;
}

// Multiply by (k-w)^w
$base = $k - $w;
$pow = pow_mod($base, $w, $mod);
$result = ($result * $pow) % $mod;

echo $result . "\n";

// Function to compute (base^exp) % mod using fast exponentiation
function pow_mod($base, $exp, $mod) {
    $result = 1;
    $base = $base % $mod;
    while ($exp > 0) {
        if ($exp % 2 == 1) {
            $result = ($result * $base) % $mod;
        }
        $exp = (int)($exp / 2);
        $base = ($base * $base) % $mod;
    }
    return $result;
}
