function modpow($base, $exp, $mod) {
    $result = 1;
    while ($exp > 0) {
        if ($exp % 2 == 1) {
            $result = ($result * $base) % $mod;
        }
        $base = ($base * $base) % $mod;
        $exp = (int)($exp / 2);
    }
    return $result;
}

function main() {
    $line = trim(fgets(STDIN));
    list($k, $w) = array_map('intval', explode(' ', $line));
    $mod = 1000000007;

    if ($w == 1) {
        echo "-1\n";
        return;
    }

    $w--;

    if ($w == 0) {
        echo "0\n";
        return;
    }

    $result = 0;

    // Calculate the sum of k * (k-1)^(i-1) for i from 1 to w
    for ($i = 1; $i <= $w; $i++) {
        $term = ($k * modpow($k - 1, $i - 1, $mod)) % $mod;
        $result = ($result + $term) % $mod;
    }

    // Multiply by k to account for the last character
    $result = ($result * $k) % $mod;

    echo $result . "\n";
}

